mapper.select:
SELECT id, account_id, watchlist_id, symbol, direction, threshold, status, last_condition_met, last_evaluated_price, last_quote_as_of, triggered_on, notification_status, notification_attempts, last_notification_error, created_on, updated_on FROM price_alerts WHERE account_id = #{accountId}
AND watchlist_id = #{watchlistId}
AND status = #{status}
ORDER BY created_on DESC, id DESC

mapper.delete:
DELETE FROM price_alerts
WHERE account_id = #{accountId}
  AND id = #{alertId}
